    j2_m6:['Compact oven module','Instrumentation Workbench, Station Modules blueprint: 6 steel plates, 3 steel components, 2 vacuum tubes, 6 bricks, 6 copper wires; later the station itself.','Utility: extractor fan and stack.'],
    j2_m4:['Feeder module','Instrumentation Workbench, Station Modules blueprint: 6 steel plates, 3 steel components, 2 vacuum tubes, 1 hopper; later the station itself.','Utility: reserve hopper.'],
    j2_m7:['Optical inspection module','Instrumentation Workbench, Station Modules blueprint: 6 steel plates, 3 steel components, 3 vacuum tubes, 3 glass panes, 1 circuit board; later the station itself.','Utility: image processing rack.'],
    j3:['Turbine jig','Instrumentation Workbench, Jigs blueprint: 4 steel plates, 2 steel components, 4 steel rods.','Tells the station which line it works for; it takes the 5 modules beside it.'],
    j3_m3:['Machining tool module','Instrumentation Workbench, Station Modules blueprint: 6 steel plates, 4 steel components, 2 vacuum tubes, 1 diamond; later the station itself.','Utility: coolant tank and chip bin.'],
    j3_m1:['Welding head module','Instrumentation Workbench, Station Modules blueprint: 6 steel plates, 3 steel components, 2 vacuum tubes, 1 graphite electrode, 6 copper wires; later the station itself.','Utility: welding power source and 2 argon cylinders.'],
    j3_m0:['Robotic arm module','Instrumentation Workbench, Station Modules blueprint: 6 steel plates, 3 steel components, 2 vacuum tubes, 1 circuit board, 3 steel rods; later the station itself.','Utility: controller cabinet with its teach pendant.'],
    j3_m7:['Optical inspection module','Instrumentation Workbench, Station Modules blueprint: 6 steel plates, 3 steel components, 3 vacuum tubes, 3 glass panes, 1 circuit board; later the station itself.','Utility: image processing rack.'],
